        click("Browser Tools");systemClick("Find on page");View find=find(activity.getWindow().getDecorView(),v->"Find text".contentEquals(v.getContentDescription()==null?"":v.getContentDescription()));check(find!=null,"Find toolbar opens");ui(()->((EditText)find).setText("second"));click("Find next");click("Close Find");click("Browser Tools");systemClick("Desktop site");await(()->"false".equals(js("navigator.userAgent.includes('Mobile')")),"Desktop site changes user agent");
        String before=browser.currentUrl();ui(()->browser.navigate("file:///data/data/com.nthexperience.desktop/shared_prefs/desktop.xml"));systemClick("OK");check(before.equals(browser.currentUrl()),"Local files are rejected without changing the page");for(String input:new String[]{"javascript:alert(1)","content://com.nthexperience.desktop.storage/document/primary:","intent://x/#Intent;end","data:text/html,hello"}){boolean blocked=false;try{BrowserUrls.address(input,"Bing");}catch(IllegalArgumentException expected){blocked=true;}check(blocked,"Address-bar scheme blocked: "+input);}
