    private String js(String script){try{BlockingQueue<String> answer=new LinkedBlockingQueue<>();runOnMainSync(()->{if(browser.web()==null)answer.offer("null");else browser.web().evaluateJavascript(script,answer::offer);});String value=answer.poll(3,TimeUnit.SECONDS);return value==null?"timeout":value;}catch(Exception ex){return "error";}}
    private void serve(){while(running)try{Socket socket=server.accept();Thread request=new Thread(()->{try(Socket client=socket){client.setSoTimeout(5000);BufferedReader reader=new BufferedReader(new InputStreamReader(client.getInputStream(),StandardCharsets.UTF_8));String line=reader.readLine();if(line==null)return;String path=line.split(" ")[1];while((line=reader.readLine())!=null&&!line.isEmpty()){}byte[] body;String type,extra="";if(path.equals("/download")){body=payload;type="text/plain";}else {String title=path.equals("/two")?"Two":path.equals("/private")?"Private":path.equals("/upload")?"Upload":"One";String page="<!doctype html><meta name='viewport' content='width=device-width, initial-scale=1'><title>"+title+"</title><style>body{font:18px sans-serif;padding:24px;color:#26455e}a{color:#1272b5}</style><h1>"+title+"</h1><p>A second page for Nth Internet.</p><a id='next' href='/two'>Next page</a>"+(path.equals("/upload")?"<input type='file' accept='text/plain'>":"")+(title.equals("One")?"<script>localStorage.setItem('fixture','working')</script>":"");body=page.getBytes(StandardCharsets.UTF_8);type="text/html";if(title.equals("One"))extra="Set-Cookie: fixture=normal; Path=/; SameSite=Lax\r\n";}OutputStream out=client.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: "+type+"; charset=utf-8\r\nContent-Length: "+body.length+"\r\nCache-Control: no-store\r\n"+extra+"Connection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.write(body);out.flush();}catch(IOException ignored){}},"browser-test-request");request.setDaemon(true);request.start();}catch(IOException ex){if(running)throw new RuntimeException(ex);}}
    private Activity awaitActivity(Class<?> type,Activity previous)throws Exception{long end=SystemClock.uptimeMillis()+20000;while(SystemClock.uptimeMillis()<end){Activity next=resumed.poll(100,TimeUnit.MILLISECONDS);if(next!=null&&next!=previous&&type.isInstance(next)&&!next.isDestroyed()){Thread.sleep(200);return next;}}throw new AssertionError("Activity unavailable: "+type.getSimpleName());}
    private void await(BooleanSupplier condition,String description)throws Exception{long end=SystemClock.uptimeMillis()+20000;while(SystemClock.uptimeMillis()<end){if(condition.getAsBoolean())return;Thread.sleep(100);}throw new AssertionError(description);}
    private View find(View root,Predicate<View> match){if(root==null||!root.isShown())return null;if(match.test(root))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View result=find(((ViewGroup)root).getChildAt(i),match);if(result!=null)return result;}return null;}
    private void click(String description){View view=find(activity.getWindow().getDecorView(),v->description.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()));check(view!=null,"Control available: "+description);ui(view::performClick);}
    private void systemClick(String text)throws Exception{await(()->node(getUiAutomation().getRootInActiveWindow(),text)!=null,"Dialog item: "+text);AccessibilityNodeInfo node=node(getUiAutomation().getRootInActiveWindow(),text);while(node!=null&&!node.isClickable())node=node.getParent();check(node!=null,"Dialog item clickable: "+text);android.graphics.Rect bounds=new android.graphics.Rect();node.getBoundsInScreen(bounds);long time=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(time,time,MotionEvent.ACTION_DOWN,bounds.exactCenterX(),bounds.exactCenterY(),0),up=MotionEvent.obtain(time,time+60,MotionEvent.ACTION_UP,bounds.exactCenterX(),bounds.exactCenterY(),0);down.setSource(InputDevice.SOURCE_TOUCHSCREEN);up.setSource(InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(down,true);getUiAutomation().injectInputEvent(up,true);down.recycle();up.recycle();Thread.sleep(200);}
    private AccessibilityNodeInfo node(AccessibilityNodeInfo root,String text){if(root==null)return null;if(text.contentEquals(root.getText()==null?"":root.getText())||text.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo result=node(root.getChild(i),text);if(result!=null)return result;}return null;}
    private void shot(String name)throws Exception{Thread.sleep(200);Bitmap bitmap=getUiAutomation().takeScreenshot();check(bitmap!=null,"Screenshot available");try(FileOutputStream out=getTargetContext().openFileOutput(name+".png",0)){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
    private void ui(Runnable action){runOnMainSync(action);try{Thread.sleep(150);}catch(InterruptedException ex){throw new AssertionError(ex);}}
    private void progress(String text){Bundle result=new Bundle();result.putString("stream","CHECK: "+text+"\n");sendStatus(1,result);}
    private void check(boolean value,String message){if(!value)throw new AssertionError(message);}
